    73	      const item = await this.getItem(sku);
    74	      const free = item.stock - item.reserved;
    75	      if (free < qty) {
    76	        throw new InsufficientStockError(sku, qty, free);
    77	      }
    78	      item.reserved += qty;
    79	      await this.store.set(skuKey(sku), item);
    80	    }
