   123	      return toReservation(order);
   124	    }
   125	    for (const { sku, qty } of order.items) {
   126	      const item = await this.getItem(sku);
   127	      item.reserved -= qty;
   128	      await this.store.set(skuKey(sku), item);
   129	    }
   130	    order.status = 'released';
   131	    await this.store.set(orderKey(orderId), order);
