'use strict';

// Reproductions for INC-5521 (see ISSUE.md). Each describe block covers one
// symptom from the incident report.

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const {
  InventoryService,
  Store,
  InsufficientStockError,
  UnknownSkuError,
  UnknownOrderError,
  OrderStateError
} = require('../src');

async function service(stock, options = {}) {
  const svc = new InventoryService(options);
  for (const [sku, qty] of Object.entries(stock)) {
    await svc.addStock(sku, qty);
  }
  return svc;
}

function times(n, fn) {
  return Array.from({ length: n }, (_, i) => fn(i));
}

// Recomputes every SKU's counters from the order records and compares them
// with the stored counters. `added` maps each SKU to the total units ever
// added to it.
async function assertLedger(svc, added, orderIds) {
  const expected = {};
  for (const sku of Object.keys(added)) {
    expected[sku] = { reserved: 0, sold: 0 };
  }
  for (const orderId of orderIds) {
    let order;
    try {
      order = await svc.getOrder(orderId);
    } catch (err) {
      if (err instanceof UnknownOrderError) {
        continue;
      }
      throw err;
    }
    for (const { sku, qty } of order.items) {
      if (order.status === 'reserved') {
        expected[sku].reserved += qty;
      } else if (order.status === 'committed') {
        expected[sku].sold += qty;
      }
    }
  }
  for (const [sku, { reserved, sold }] of Object.entries(expected)) {
    const snap = await svc.snapshot(sku);
    assert.deepEqual(snap, { sku, stock: added[sku] - sold, reserved, sold }, `counters for ${sku}`);
    assert.ok(snap.stock - snap.reserved >= 0, `available for ${sku} went negative`);
  }
}

// A store whose calls on a held key wait until the key is opened again.
class GatedStore extends Store {
  constructor() {
    super();
    this.gates = new Map();
  }

  hold(key) {
    let open;
    this.gates.set(key, new Promise(resolve => { open = resolve; }));
    return () => {
      this.gates.delete(key);
      open();
    };
  }

  async get(key) {
    await this.gates.get(key);
    return super.get(key);
  }

  async set(key, value) {
    await this.gates.get(key);
    return super.set(key, value);
  }
}

// A store that delays each call by a random number of event-loop turns, so
// concurrent calls interleave in many orders. Seeded, so runs repeat.
class JitterStore extends Store {
  constructor(random) {
    super();
    this.random = random;
  }

  async get(key) {
    await this.jitter();
    return super.get(key);
  }

  async set(key, value) {
    await this.jitter();
    return super.set(key, value);
  }

  async keys(prefix) {
    await this.jitter();
    return super.keys(prefix);
  }

  async jitter() {
    const turns = Math.floor(this.random() * 4);
    for (let i = 0; i < turns; i++) {
      await new Promise(resolve => setImmediate(resolve));
    }
  }
}

// mulberry32
function seededRandom(seed) {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function withTimeout(promise, ms, what) {
  let timer;
  const timeout = new Promise((_, reject) => {
    timer = setTimeout(() => reject(new Error(`${what} did not finish within ${ms}ms`)), ms);
  });
  return Promise.race([promise, timeout]).finally(() => clearTimeout(timer));
}

describe('oversold stock: 263 orders confirmed for 250 units', () => {
  it('holds no more than the units on hand when many checkouts reserve at once', async () => {
    const svc = await service({ 'sneaker-limited': 250 });
    const results = await Promise.allSettled(
      times(300, i => svc.reserve(`o${i}`, [{ sku: 'sneaker-limited', qty: 1 }]))
    );
    const held = results.filter(r => r.status === 'fulfilled');
    const refused = results.filter(r => r.status === 'rejected');
    assert.equal(held.length, 250);
    for (const { reason } of refused) {
      assert.ok(reason instanceof InsufficientStockError, `unexpected rejection: ${reason}`);
      assert.equal(reason.available, 0);
    }
    assert.deepEqual(await svc.snapshot('sneaker-limited'),
      { sku: 'sneaker-limited', stock: 250, reserved: 250, sold: 0 });

    await Promise.all(held.map(r => svc.commit(r.value.orderId)));
    assert.deepEqual(await svc.snapshot('sneaker-limited'),
      { sku: 'sneaker-limited', stock: 0, reserved: 0, sold: 250 });
  });

  it('does not oversell when each worker has its own service on the shared store', async () => {
    const store = new Store();
    const workers = times(40, () => new InventoryService({ store }));
    await workers[0].addStock('sneaker-limited', 250);
    const results = await Promise.allSettled(
      times(300, i => workers[i % workers.length].reserve(`o${i}`, [{ sku: 'sneaker-limited', qty: 1 }]))
    );
    assert.equal(results.filter(r => r.status === 'fulfilled').length, 250);
    assert.equal(await workers[0].available('sneaker-limited'), 0);
  });

  it('keeps every unit when stock is added concurrently, including to a new sku', async () => {
    const svc = new InventoryService();
    await Promise.all(times(20, () => svc.addStock('widget', 5)));
    assert.equal((await svc.snapshot('widget')).stock, 100);
  });

  it('keeps stock added while reservations are being taken', async () => {
    const svc = await service({ widget: 10 });
    await Promise.all([
      ...times(10, i => svc.reserve(`o${i}`, [{ sku: 'widget', qty: 1 }])),
      ...times(10, () => svc.addStock('widget', 1))
    ]);
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 20, reserved: 10, sold: 0 });
  });
});

describe('reserved went negative and did not recover', () => {
  it('refuses to release a committed order', async () => {
    const svc = await service({ widget: 10 });
    await svc.reserve('o1', [{ sku: 'widget', qty: 3 }]);
    await svc.commit('o1');
    await assert.rejects(svc.release('o1'), err => {
      assert.ok(err instanceof OrderStateError);
      assert.equal(err.status, 'committed');
      return true;
    });
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 7, reserved: 0, sold: 3 });
    assert.equal((await svc.commit('o1')).status, 'committed');
  });

  it('applies exactly one of a concurrent commit and release', async () => {
    const svc = await service({ widget: 10 });
    await svc.reserve('o1', [{ sku: 'widget', qty: 3 }]);
    const [commit, release] = await Promise.allSettled([svc.commit('o1'), svc.release('o1')]);
    const outcomes = [commit.status, release.status].sort();
    assert.deepEqual(outcomes, ['fulfilled', 'rejected']);
    const rejected = commit.status === 'rejected' ? commit : release;
    assert.ok(rejected.reason instanceof OrderStateError);
    await assertLedger(svc, { widget: 10 }, ['o1']);
  });

  it('returns the units of concurrent releases of one order once', async () => {
    const svc = await service({ widget: 10 });
    await svc.reserve('o1', [{ sku: 'widget', qty: 3 }]);
    await svc.reserve('o2', [{ sku: 'widget', qty: 2 }]);
    const results = await Promise.all(times(5, () => svc.release('o1')));
    assert.ok(results.every(r => r.status === 'released'));
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 10, reserved: 2, sold: 0 });
  });

  it('expire releases only stale reserved orders and reports only those', async () => {
    let t = 0;
    const svc = await service({ widget: 10 }, { now: () => t, reservationTtlMs: 1000 });
    await svc.reserve('committed', [{ sku: 'widget', qty: 1 }]);
    await svc.reserve('released', [{ sku: 'widget', qty: 2 }]);
    await svc.reserve('stale', [{ sku: 'widget', qty: 3 }]);
    await svc.commit('committed');
    await svc.release('released');
    t = 900;
    await svc.reserve('fresh', [{ sku: 'widget', qty: 4 }]);
    t = 5000;

    assert.deepEqual(await svc.expire(), ['stale']);
    assert.equal((await svc.commit('committed')).status, 'committed');
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 9, reserved: 4, sold: 1 });
    assert.deepEqual(await svc.expire(), ['fresh']);
    assert.deepEqual(await svc.expire(), []);
    await assertLedger(svc, { widget: 10 }, ['committed', 'released', 'stale', 'fresh']);
  });

  it('applies exactly one of a commit and an expire that race for the same order', async () => {
    let t = 0;
    const svc = await service({ widget: 10 }, { now: () => t, reservationTtlMs: 1000 });
    await svc.reserve('o1', [{ sku: 'widget', qty: 2 }]);
    t = 5000;
    const [commit, expire] = await Promise.allSettled([svc.commit('o1'), svc.expire()]);
    assert.equal(expire.status, 'fulfilled');
    if (commit.status === 'fulfilled') {
      assert.deepEqual(expire.value, []);
    } else {
      assert.ok(commit.reason instanceof OrderStateError);
      assert.deepEqual(expire.value, ['o1']);
    }
    await assertLedger(svc, { widget: 10 }, ['o1']);
  });
});

describe('retried checkout held units twice for one order', () => {
  it('holds the units once when a retry arrives while the first attempt is in flight', async () => {
    const svc = await service({ widget: 10 });
    const results = await Promise.all(times(5, () => svc.reserve('o1', [{ sku: 'widget', qty: 2 }])));
    for (const reservation of results) {
      assert.deepEqual(reservation, { orderId: 'o1', status: 'reserved', items: [{ sku: 'widget', qty: 2 }] });
    }
    assert.equal(await svc.available('widget'), 8);
    await svc.release('o1');
    assert.equal(await svc.available('widget'), 10);
  });

  it('lets a retry reserve after the first attempt was refused', async () => {
    const svc = await service({ widget: 1 });
    await svc.reserve('other', [{ sku: 'widget', qty: 1 }]);
    const first = svc.reserve('o1', [{ sku: 'widget', qty: 1 }]);
    const release = svc.release('other');
    const retry = svc.reserve('o1', [{ sku: 'widget', qty: 1 }]);
    await assert.rejects(first, InsufficientStockError);
    await release;
    assert.equal((await retry).status, 'reserved');
    assert.equal(await svc.available('widget'), 0);
  });
});

describe('a refused bundle left its other item held', () => {
  it('holds nothing when one item of a bundle is out of stock', async () => {
    const svc = await service({ shoe: 5, lace: 0 });
    await assert.rejects(
      svc.reserve('o1', [{ sku: 'shoe', qty: 1 }, { sku: 'lace', qty: 1 }]),
      InsufficientStockError
    );
    assert.equal(await svc.available('shoe'), 5);
    await assert.rejects(svc.getOrder('o1'), UnknownOrderError);
  });

  it('holds nothing when one item of a bundle is an unknown sku', async () => {
    const svc = await service({ shoe: 5 });
    await assert.rejects(svc.reserve('o1', [{ sku: 'shoe', qty: 1 }, { sku: 'nope', qty: 1 }]), UnknownSkuError);
    assert.equal(await svc.available('shoe'), 5);
  });

  it('gives the last unit of a bundle item to exactly one of many concurrent bundles', async () => {
    const svc = await service({ shoe: 10, lace: 1 });
    const results = await Promise.allSettled(
      times(10, i => svc.reserve(`o${i}`, [{ sku: 'shoe', qty: 1 }, { sku: 'lace', qty: 1 }]))
    );
    assert.equal(results.filter(r => r.status === 'fulfilled').length, 1);
    assert.equal(await svc.available('shoe'), 9);
    assert.equal(await svc.available('lace'), 0);
  });

  it('completes bundles that list the same skus in opposite orders', { timeout: 5000 }, async () => {
    const svc = await service({ shoe: 100, lace: 100 });
    await Promise.all(times(40, i => svc.reserve(`o${i}`, i % 2
      ? [{ sku: 'shoe', qty: 1 }, { sku: 'lace', qty: 1 }]
      : [{ sku: 'lace', qty: 1 }, { sku: 'shoe', qty: 1 }])));
    assert.equal(await svc.available('shoe'), 60);
    assert.equal(await svc.available('lace'), 60);
  });
});

describe('sold counts higher than orders shipped', () => {
  it('counts the units of concurrent commits of one order once', async () => {
    const svc = await service({ widget: 10 });
    await svc.reserve('o1', [{ sku: 'widget', qty: 3 }]);
    const results = await Promise.all(times(5, () => svc.commit('o1')));
    assert.ok(results.every(r => r.status === 'committed'));
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 7, reserved: 0, sold: 3 });
  });

  it('counts every order when different orders of one sku commit at once', async () => {
    const svc = await service({ widget: 30 });
    for (const i of times(20, i => i)) {
      await svc.reserve(`o${i}`, [{ sku: 'widget', qty: 1 }]);
    }
    await Promise.all(times(20, i => svc.commit(`o${i}`)));
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 10, reserved: 0, sold: 20 });
  });
});

describe('calls that share no sku and no order', () => {
  it('do not wait for a stalled call on another sku', async () => {
    const store = new GatedStore();
    const svc = new InventoryService({ store });
    await svc.addStock('slow', 5);
    await svc.addStock('fast', 5);
    await svc.reserve('fast-1', [{ sku: 'fast', qty: 1 }]);

    const open = store.hold('sku:slow');
    const stalled = svc.reserve('slow-1', [{ sku: 'slow', qty: 1 }]);
    await withTimeout(svc.reserve('fast-2', [{ sku: 'fast', qty: 1 }]), 1000, 'reserve on another sku');
    await withTimeout(svc.commit('fast-1'), 1000, 'commit on another sku');
    await withTimeout(svc.release('fast-2'), 1000, 'release on another sku');
    await withTimeout(svc.addStock('fast', 1), 1000, 'addStock on another sku');

    open();
    assert.equal((await stalled).status, 'reserved');
    assert.deepEqual(await svc.snapshot('fast'), { sku: 'fast', stock: 5, reserved: 0, sold: 1 });
  });
});

describe('concurrent checkout traffic', () => {
  it('keeps every counter consistent with the orders under random interleavings', async () => {
    const random = seededRandom(5521);
    const pick = list => list[Math.floor(random() * list.length)];
    let t = 0;
    const svc = new InventoryService({ store: new JitterStore(random), now: () => ++t, reservationTtlMs: 40 });
    const added = { a: 15, b: 15, c: 15 };
    const skus = Object.keys(added);
    for (const sku of skus) {
      await svc.addStock(sku, added[sku]);
    }
    const orderIds = times(80, i => `o${i}`);

    const calls = times(500, () => {
      const orderId = pick(orderIds);
      const roll = random();
      if (roll < 0.4) {
        const items = skus.filter(() => random() < 0.5).map(sku => ({ sku, qty: 1 + Math.floor(random() * 3) }));
        return svc.reserve(orderId, items.length > 0 ? items : [{ sku: pick(skus), qty: 1 }]);
      }
      if (roll < 0.65) {
        return svc.commit(orderId);
      }
      if (roll < 0.85) {
        return svc.release(orderId);
      }
      if (roll < 0.95) {
        return svc.expire();
      }
      const sku = pick(skus);
      added[sku] += 1;
      return svc.addStock(sku, 1);
    });

    const results = await Promise.allSettled(calls);
    const expectedErrors = [InsufficientStockError, UnknownOrderError, OrderStateError];
    for (const result of results) {
      if (result.status === 'rejected') {
        assert.ok(expectedErrors.some(type => result.reason instanceof type), `unexpected error: ${result.reason}`);
      }
    }
    const statuses = await Promise.allSettled(orderIds.map(id => svc.getOrder(id)));
    assert.ok(statuses.some(r => r.status === 'fulfilled' && r.value.status === 'committed'), 'no order committed');
    assert.ok(statuses.some(r => r.status === 'fulfilled' && r.value.status === 'released'), 'no order released');
    await assertLedger(svc, added, orderIds);
  });
});

