'use strict';

/**
 * Mutual exclusion per key for async callers in one process.
 *
 * A caller waits only for earlier holders of the keys it asks for, so work on
 * unrelated keys runs concurrently. Waiters are served first come, first
 * served. A key's entry is removed once nobody holds or waits for it, so
 * memory is bounded by the keys in use, not by every key ever locked.
 */
class KeyedLock {
  constructor() {
    // A key is present while it is held; its value is the queue of waiters.
    this.queues = new Map();
  }

  /**
   * Run fn while holding every key in keys, and return what it returns.
