'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { KeyedLock } = require('../src/lock');

function gate() {
  let open;
  const opened = new Promise(resolve => { open = resolve; });
  return { opened, open };
}

function tick() {
  return new Promise(resolve => setImmediate(resolve));
}

describe('KeyedLock', () => {
  it('returns the result of fn and forgets the key once released', async () => {
    const lock = new KeyedLock();
    assert.equal(await lock.run(['a', 'b'], async () => 42), 42);
    assert.equal(lock.size, 0);
  });

  it('runs callers of one key one at a time, in arrival order', async () => {
    const lock = new KeyedLock();
    const order = [];
    let inside = 0;
    await Promise.all([1, 2, 3, 4].map(n => lock.run(['a'], async () => {
      inside += 1;
      assert.equal(inside, 1, 'two callers held the same key');
      await tick();
      order.push(n);
      inside -= 1;
    })));
    assert.deepEqual(order, [1, 2, 3, 4]);
    assert.equal(lock.size, 0);
  });

  it('does not make a caller wait for a holder of a different key', async () => {
    const lock = new KeyedLock();
    const { opened, open } = gate();
    const holder = lock.run(['a'], () => opened);
    assert.equal(await lock.run(['b'], async () => 'b ran'), 'b ran');
    open();
    await holder;
  });

  it('makes a caller wait while any one of its keys is held', async () => {
    const lock = new KeyedLock();
    const { opened, open } = gate();
    const holder = lock.run(['b'], () => opened);
    let ran = false;
    const waiter = lock.run(['a', 'b'], async () => { ran = true; });
    await tick();
    assert.equal(ran, false);
    open();
    await Promise.all([holder, waiter]);
    assert.equal(ran, true);
  });

  it('releases the keys when fn throws', async () => {
    const lock = new KeyedLock();
    await assert.rejects(lock.run(['a'], async () => { throw new Error('boom'); }), /boom/);
    assert.equal(lock.size, 0);
    assert.equal(await lock.run(['a'], async () => 'next'), 'next');
  });

  it('takes a key listed twice only once', async () => {
    const lock = new KeyedLock();
    assert.equal(await lock.run(['a', 'a'], async () => 'ok'), 'ok');
    assert.equal(lock.size, 0);
  });
});

