'use strict';

const { Store } = require('./store');
const { KeyedLock } = require('./lock');
const {
  ValidationError,
  UnknownSkuError,
  UnknownOrderError,
  InsufficientStockError,
  OrderStateError
} = require('./errors');

const DEFAULT_TTL_MS = 15 * 60 * 1000;

// Locks belong to the store rather than to one service, so every service in
// this process that shares a store object also shares its locks.
const locksByStore = new WeakMap();

/**
 * Stock reservations for checkout.
 *
 * Every SKU has three counters: `stock` (units on hand), `reserved` (units
 * held for orders that have not been committed) and `sold`. Available stock
 * is `stock - reserved` and must never go below zero.
 *
 * An order moves reserved -> committed, or reserved -> released. Committing
 * turns its held units into sold units; releasing returns them.
 *
 * The service is called concurrently by every checkout worker. Each
 * read-modify-write runs under per-key locks: the order's lock for anything
 * that reads and then changes an order, and the lock of every SKU whose
 * counters it changes. Calls that share no SKU and no order never wait for
 * each other. The order lock is always taken before any SKU lock, and SKU
 * locks in sorted order, so calls cannot deadlock.
 *
 * The locks cover one process. Services on the same store object share them;
 * workers in separate processes would need atomic updates from the store.
 */
class InventoryService {
  constructor({ store = new Store(), reservationTtlMs = DEFAULT_TTL_MS, now = () => Date.now() } = {}) {
    this.store = store;
    this.ttl = reservationTtlMs;
    this.now = now;
    this.locks = locksFor(store);
  }

  /** Add units to a SKU, creating it if needed. Returns the SKU snapshot. */
  async addStock(sku, qty) {
    assertSku(sku);
    assertQty(qty);
    return this.locks.run([skuKey(sku)], async () => {
      const item = (await this.store.get(skuKey(sku))) || { stock: 0, reserved: 0, sold: 0 };
      item.stock += qty;
      await this.store.set(skuKey(sku), item);
      return { sku, ...item };
    });
  }

  /** Units that can still be reserved. */
  async available(sku) {
    const item = await this.getItem(sku);
    return item.stock - item.reserved;
  }

  /** The SKU's counters. */
  async snapshot(sku) {
    const item = await this.getItem(sku);
    return { sku, stock: item.stock, reserved: item.reserved, sold: item.sold };
  }

  /**
   * Hold stock for an order: all of its items, or none of them.
   *
   * Idempotent by orderId: checkout retries a timed-out request with the same
   * orderId, and a retry must return the existing reservation rather than
   * hold the stock twice.
   *
   * Rejects with InsufficientStockError when any item cannot be held, and
   * then holds nothing.
   */
  async reserve(orderId, items) {
    assertOrderId(orderId);
    assertItems(items);
    // Copied before the first await: the caller may reuse the array while
    // this call waits for locks.
    const wanted = items.map(({ sku, qty }) => ({ sku, qty }));
    return this.withOrderLock(orderId, async () => {
      const existing = await this.store.get(orderKey(orderId));
      if (existing) {
        return toReservation(existing);
      }
      await this.updateItems(wanted, (item, sku, qty) => {
        const free = item.stock - item.reserved;
        if (free < qty) {
          throw new InsufficientStockError(sku, qty, free);
        }
        item.reserved += qty;
      });
      const order = { orderId, items: wanted, status: 'reserved', createdAt: this.now() };
      await this.store.set(orderKey(orderId), order);
      return toReservation(order);
    });
  }

  /**
